package cl.bancoxyz.mobilebff;import java.util.*;import org.springframework.cloud.client.loadbalancer.LoadBalanced;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;@RestController @RequestMapping("/api/mobile") public class MobileController{private final RestClient.Builder client;public MobileController(@LoadBalanced RestClient.Builder c){client=c;}@GetMapping("/summary/{accountId}") public Map<String,Object> summary(@PathVariable long accountId){Object account=client.build().get().uri("http://account-service/api/accounts/{id}",accountId).retrieve().body(Object.class);return Map.of("channel","mobile","account",account,"payload","lightweight");}}